SELECT A.svcno, A.custcd, b.custnm, A.svcymd, A.trb_ment as trbment, A.ans_ment as ansment, A.ai_summary as aisummary, A.start_time as starttime, A.end_time as endtime, A.consultid, C.USERNM AS consultnm, A.rec_file as recfile, A.escalation_no as escalationno, A.esc_memo as escmemo, A.call_telno as calltelno, A.call_usernm as callusernm, A.call_email as callemail, E.feedback_user as feedbackuser, IFNULL(D.USERNM,'') AS feedbackusernm FROM call_mst_tbl A LEFT OUTER JOIN HABA020T_TBL B ON A.CMPYCD = B.CMPYCD AND A.CUSTCD = B.CUSTCD LEFT OUTER JOIN HABA920T_TBL C ON A.CMPYCD = C.CMPYCD AND A.CONSULTID = C.USERID LEFT OUTER JOIN cti_escalation_tbl E on A.escalation_no = E.escalation_no LEFT OUTER JOIN HABA920T_TBL D ON A.CMPYCD = D.CMPYCD AND E.feedback_user = D.USERID WHERE A.CMPYCD = #{cmpycd} and escalation_yn = 'Y' and svcymd BETWEEN #{sdate} AND #{edate}
AND E.feedback_user = #{userid}
ORDER BY A.SALESID DESC

